add("Electromagnetic induction", [
    ("What is electromagnetic induction?", "Making a current (or emf) by changing magnetic field through a coil?", "Move magnet in coil. Current?", "Stay on this.", "Induction is a plant tropism.", "A changing field through a coil can make current.", "That's it — that's induction."),
    ("What do you need to induce a current in a closed coil?", "A changing flux — move magnet, move coil, or change I in a neighbour?", "Change. Not a still magnet in a still coil?", "Stay on this.", "A still magnet in a still coil always drives huge current.", "A change in the magnetic field through it.", "That's it — change is required."),
    ("What is Faraday's idea, school-level?", "Induced emf related to how fast the flux changes?", "Faster motion, bigger effect? Rate?", "Stay on induction.", "Faraday said magnets eat current.", "Faster change, larger induced emf.", "That's it — rate of change matters."),
    ("What is a generator's school idea?", "Turn a coil in a field (or field past a coil) to induce current?", "Bike dynamo. Rotation?", "That's induction in a machine?", "Generators store sugar.", "Motion plus field → induced current.", "That's it — a generator uses induction."),
    ("Does a steady field through a still coil induce current?", "No — no change, no induced current in the school rule?", "Still bar magnet inside. Current?", "Change needed?", "Steady field always induces more.", "No change, no induced current.", "That's it — steady and still isn't enough."),
    ("What is Lenz's law pointing at, loosely?", "The induced current fights the change that caused it?", "Opposition. Lenz?", "Don't need full calculus?", "Lenz's law is about acids.", "Induced effects oppose the change.", "That's it — opposition to the change."),
    ("Can a changing current in one coil affect another?", "Yes — transformer idea: changing I, changing field, induced in the other?", "Two coils. Mutual?", "Stay on induction.", "Coils never affect each other.", "Yes — a changing current can induce in a neighbour.", "That's it — that's the transformer seed."),
    ("Why move the magnet faster in a demo?", "Larger rate of change, bigger induced current (meter flicks more)?", "Speed. Flick?", "Stay on this.", "Faster motion always kills the field.", "Faster change, bigger induced effect.", "That's it — faster gives a bigger flick."),
    ("Is induction the same as an electromagnet?", "Electromagnet: current makes field. Induction: changing field makes current?", "Reverse jobs. Unmix?", "Stay on this.", "They are the same word.", "No — opposite directions of the idea.", "That's it — you unmixed them."),
    ("What is flux, loosely in school?", "How much field 'goes through' the coil's face?", "Field through area. Flux?", "Change of that induces?", "Flux is a type of water only.", "Field through the coil's area.", "That's it — flux is field through the loop."),
])

add("Magnetic field around a current-carrying conductor", [
    ("Does a current make a magnetic field?", "Yes — a wire with current has a field around it?", "Compass near a wire. Deflect?", "Stay on this.", "Current never makes a field.", "Yes — current produces a magnetic field.", "That's it — current makes a field."),
    ("What is the pattern around a straight wire, school?", "Circles around the wire?", "Iron filings / compasses. Circles?", "Right-hand grip?", "The field is a straight arrow only along the wire always.", "Circular around the wire.", "That's it — circular field around a straight wire."),
    ("What is the right-hand grip rule for?", "Thumb in current direction, fingers show field circles?", "Grip. Direction?", "Stay on this.", "The left foot shows current.", "Relating I direction to field direction.", "That's it — grip maps I to field."),
    ("What if current is reversed?", "Field circles reverse?", "Compass flips. Reverse I?", "Stay on this.", "Reverse current leaves the field identical.", "The field direction reverses.", "That's it — reverse I, reverse field."),
    ("Is this field the same as a bar magnet's shape?", "Different pattern for a single wire; a coil can look bar-like?", "Straight wire vs solenoid. Different maps?", "Don't force one picture?", "Every field is a bar magnet drawing.", "A straight wire is circular, not bar-shaped.", "That's it — wire vs bar have different maps."),
    ("What happens if I is zero?", "Field from that current disappears?", "Switch off. Compass back?", "Stay on this.", "The field stays forever.", "No current, no that field.", "That's it — no I, no current-field."),
    ("Why compasses in Oersted's story moved?", "They detected the wire's magnetic field?", "Historic demo. Compass?", "Stay on current and magnetism.", "Compasses detect pH.", "The current's field nudged them.", "That's it — Oersted's compasses felt the wire's field."),
    ("Does a stronger current make a stronger field, school?", "Yes — field around the wire increases with I?", "More I, more effect on compass?", "Stay on this.", "More current always kills magnetism.", "Stronger I, stronger field.", "That's it — field grows with current."),
    ("Can two wires with current affect each other?", "Yes — each sits in the other's field (forces between wires)?", "Later: motors. Two wires?", "Don't need full ampère law?", "Wires never feel magnetism.", "Yes — current-fields can push wires.", "That's it — currents can magnetically push."),
    ("Is the field a material coming out of the copper?", "It's a field in the space around, not copper powder spraying?", "Invisible influence. Field?", "Stay conceptual Grade 10.", "Copper dust is the field.", "A magnetic field in the surrounding space.", "That's it — a field around, not copper spray."),
])

add("Ionic bond formation", [
    ("What is an ionic bond?", "Attraction after electrons transfer, making + and − ions?", "NaCl story. Transfer then stick?", "Stay on this.", "Ionic bond is a shared pair only always.", "Transfer of electrons, then opposite ions attract.", "That's it — ionic is transfer plus attraction."),
    ("What does sodium do in the NaCl school picture?", "Lose one electron to form Na+?", "Metal. Lose e−?", "Not gain two?", "Sodium gains seven electrons here.", "It loses one electron.", "That's it — Na loses one."),
    ("What does chlorine do in that picture?", "Gain one electron to form Cl−?", "Non-metal. Gain?", "Complete the outer shell story?", "Chlorine loses seven here.", "It gains one electron.", "That's it — Cl gains one."),
    ("Why do the ions stick?", "Opposite charges attract?", "Plus and minus. Stick?", "Not a covalent share as the main NaCl story?", "They stick with gravity only.", "Electrostatic attraction.", "That's it — opposite charges attract."),
    ("What is a lattice here?", "A giant regular stack of ions, not a single NaCl molecule?", "Crystal. Lattice?", "Don't draw one pair as the whole crystal?", "NaCl is a tiny two-atom gas molecule only.", "A giant ionic structure.", "That's it — a lattice of ions."),
    ("Why do ionic solids often not conduct, but melts/solutions can?", "Ions must be free to move to carry current?", "Solid vs molten. Mobile ions?", "Stay on bonding/electricity link.", "Solid salt is the best wire always.", "Mobile ions conduct; locked ions don't.", "That's it — mobile ions are needed."),
    ("Is this the same as covalent sharing?", "No — transfer vs share?", "NaCl vs CH4. Unmix?", "Stay on this.", "They are identical.", "No — transfer vs share.", "That's it — you unmixed ionic and covalent."),
    ("What is an ion?", "An atom (or group) with a charge after losing/gaining electrons?", "Na+, Cl−. Charged?", "Not a neutral atom?", "An ion is a type of wave.", "A charged particle from electron change.", "That's it — ion means charged."),
    ("Why metals with non-metals often go ionic in school?", "Metals tend to lose, non-metals gain, toward full shells?", "Left–right of table. Transfer?", "Not always, but the Grade-10 pattern?", "Metals share with metals as NaCl.", "Lose-and-gain pairs well.", "That's it — metal + non-metal often transfer."),
    ("What is a formula unit of NaCl, loosely?", "The ratio 1:1 in the lattice, not a separate molecule?", "NaCl as a ratio. Formula?", "Stay on ionic compounds.", "NaCl means nine chlorines.", "The simplest ion ratio.", "That's it — formula is the ratio."),
])

